import java.util.*;

class Coordinate {
    private int x;
    private int y;

    public Coordinate(int x, int y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Coordinate)) return false;
        Coordinate c = (Coordinate) o;
        return x == c.x && y == c.y;
    }
}

public class Main {
    public static void main(String[] args) {
        Map<Coordinate, String> labels = new HashMap<>();
        labels.put(new Coordinate(1, 1), "origin-ish");

        System.out.println(labels.containsKey(new Coordinate(1, 1)));   // expected true, prints false
    }
}

